use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for profile in 0..8{for scale in[0.25f32,0.5,1.]{let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut out=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="transform").unwrap().instance();let(sh,sw,uniform,skew,axis,rotation,opacity,shutter) = match profile{0=>(100.,100.,true,0.,0.,0.,100.,0.),1=>(75.,125.,false,12.5,37.25,-37.25,62.5,180.),2=>(25.,50.,false,-70.,90.,359.9,100.,360.),3=>(0.,100.,true,0.,0.,0.,100.,0.),4=>(10000.,10000.,false,70.,-720.,720.,0.01,0.),5=>(100.,0.,false,0.,0.,45.,0.,0.),6=>(50.,50.,true,0.,0.,0.,100.,0.),_=>(100.,100.,true,0.,0.,90.,100.,0.)};for(n,v)in[("scale_height",sh),("scale_width",sw),("skew",skew),("skew_axis",axis),("rotation",rotation),("opacity",opacity),("shutter_angle",shutter)]{e.params.insert(n.into(),Param::new(ParamValue::Float(v)));}e.params.insert("uniform_scale".into(),Param::new(ParamValue::Bool(uniform)));let authored=profile%2==1;let anchor=if authored{json!([1.123456789012,null])}else{json!(null)};let position=if authored{json!([null,-0.75])}else{json!(null)};if authored{for(n,x,y)in[("anchor",1.123456789012,f64::NAN),("position",f64::NAN,-0.75)]{e.params.insert(n.into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(x,y))));}}
let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:scale,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut out,&e,&cx);cases.push(json!({"parameters":{"anchor":anchor,"position":position,"uniformScale":uniform,"scaleHeight":sh,"scaleWidth":sw,"skew":skew,"skewAxis":axis,"rotation":rotation,"opacity":opacity,"shutterAngle":shutter},"width":w,"height":h,"rgba":rgba,"scale":scale,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}}let mut media=vec![];
{for tick in[0u64,250000,500000]{
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,if i%16<8&&i/16<12{128}else{0}]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000){let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="transform").unwrap().instance();for((n,a),b)in ["scale_height", "scale_width", "skew", "skew_axis", "rotation", "opacity", "shutter_angle"].iter().zip([100.0, 100.0, 0.0, 0.0, 0.0, 100.0, 0.0]).zip([25.0, 50.0, 12.5, 37.25, -37.25, 62.5, 180.0]){e.params.insert((*n).into(),Param::new(ParamValue::Float(a+(b-a)*t)));}e.params.insert("uniform_scale".into(),Param::new(ParamValue::Bool(false)));for(n,x,y)in[("anchor",4.+t*4.,4.+t*4.),("position",4.+t*8.,4.+t*8.)]{e.params.insert(n.into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(x,y))));}
let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}